import { useCallback, useEffect, useRef, useState } from 'react';
import { Activity, AlertTriangle, ArrowLeft, BarChart3, BookOpen, Camera, Check, ChevronRight, CircleUserRound, Cloud, CloudOff, Database, Eye, FileImage, History, Home, ImagePlus, Info, Leaf, Link2, LogOut, Menu, RefreshCw, ScanLine, Search, Settings, ShieldCheck, Trash2, Upload, Users, X } from 'lucide-react';
import { analyzeLeaf } from './services/inferenceService';
import { api, authenticate, getToken, logout, setToken } from './services/api';

const THRESHOLD = Number(import.meta.env.VITE_CONFIDENCE_THRESHOLD ?? 70);
const FARMER_NAV = [['/farmer/dashboard', 'Home', Home], ['/farmer/scan', 'Scan', ScanLine], ['/farmer/history', 'History', History], ['/farmer/diseases', 'Guide', BookOpen], ['/farmer/profile', 'Profile', CircleUserRound]];
const ADMIN_NAV = [['/admin/dashboard', 'Dashboard', Home], ['/admin/farmers', 'Farmers', Users], ['/admin/diagnoses', 'Diagnoses', ScanLine], ['/admin/diseases', 'Disease Knowledge', BookOpen], ['/admin/sources', 'Research Sources', Link2], ['/admin/analytics', 'Analytics', BarChart3], ['/admin/system', 'Model Information', Settings], ['/admin/profile', 'Profile', CircleUserRound]];
const formatDate = (value, time = false) => value ? new Intl.DateTimeFormat('en-PH', { month: 'short', day: 'numeric', year: 'numeric', ...(time ? { hour: 'numeric', minute: '2-digit' } : {}) }).format(new Date(value)) : 'Not available';
const titleCase = (value = '') => value.replaceAll('-', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
const confidenceText = (value) => value < THRESHOLD ? 'Uncertain result' : value >= 85 ? 'High confidence' : 'Moderate confidence';
const mapDiagnosis = (item) => ({ id: String(item.id), diseaseId: item.disease?.slug || item.predicted_class, disease: item.disease, confidence: Number(item.confidence), date: item.diagnosed_at, source: item.source, synced: item.sync_status === 'synced' || item.source === 'web', isSimulated: Boolean(item.is_simulated), image: item.image_url, latency: item.inference_time_ms || 0, model: item.model_version || 'Not specified', user: item.user });

function IconButton({ label, children, ...props }) { return <button className="icon-button" aria-label={label} title={label} {...props}>{children}</button>; }
function LogoMark({ inverse = false }) { return <img className="logo-mark" src={inverse ? '/assets/brand/dahonmd-logo-white.png' : '/assets/brand/dahonmd-logo-green.png'} alt="" aria-hidden="true" />; }
function Loading({ text = 'Loading...' }) { return <div className="role-loading"><RefreshCw className="spin" size={24} /><p>{text}</p></div>; }
function Empty({ icon: Icon = Leaf, title, text, action, actionLabel }) { return <div className="empty-state role-empty"><Icon size={30} /><h3>{title}</h3><p>{text}</p>{action && <button className="primary-button" onClick={action}>{actionLabel}</button>}</div>; }

function AuthPage({ mode, onAuthenticated, navigate }) {
  const signup = mode === 'register'; const [form, setForm] = useState({ name: '', email: '', password: '', password_confirmation: '' }); const [error, setError] = useState(''); const [errors, setErrors] = useState({}); const [busy, setBusy] = useState(false);
  const submit = async (event) => { event.preventDefault(); setBusy(true); setError(''); setErrors({}); try { const user = await authenticate(mode, form); onAuthenticated(user); navigate(user.role === 'admin' ? '/admin/dashboard' : '/farmer/dashboard'); } catch (exception) { setError(exception.message); setErrors(exception.errors || {}); } finally { setBusy(false); } };
  return <main className="auth-page"><section className="auth-card role-auth-card"><div className="auth-brand"><span className="brand-mark"><LogoMark /></span><div><strong>DahonMD</strong><small>LEAF HEALTH GUIDE</small></div></div><p className="eyebrow">{signup ? 'CREATE FARMER ACCOUNT' : 'WELCOME BACK'}</p><h1>{signup ? 'Start checking your banana plants' : 'Sign in to continue'}</h1><p className="auth-intro">One account keeps your scans, guide, and history together.</p><form className="auth-form" onSubmit={submit}>{signup && <label>Full name<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required />{errors.name && <small>{errors.name[0]}</small>}</label>}<label>Email<input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} required />{errors.email && <small>{errors.email[0]}</small>}</label><label>Password<input type="password" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} required />{errors.password && <small>{errors.password[0]}</small>}</label>{signup && <label>Confirm password<input type="password" value={form.password_confirmation} onChange={(event) => setForm({ ...form, password_confirmation: event.target.value })} required /></label>}{error && <div className="form-error">{error}</div>}<button className="primary-button" disabled={busy}>{busy ? 'Please wait...' : signup ? 'Create Farmer Account' : 'Sign In'}</button></form><p className="auth-switch">{signup ? 'Already have an account?' : 'Need an account?'} <button onClick={() => navigate(signup ? '/login' : '/signup')}>{signup ? 'Sign in' : 'Create farmer account'}</button></p></section></main>;
}

function Shell({ role, user, path, navigate, onSignedOut, children, online }) {
  const items = role === 'admin' ? ADMIN_NAV : FARMER_NAV;
  const currentSection = items.find(([route]) => route === path)?.[1] || 'Home';
  const [open, setOpen] = useState(false);
  const signOut = async () => { await logout(); onSignedOut(); };

  return <div className={`role-shell ${role}-shell`}>
    {open && <button className="role-scrim" aria-label="Close menu" onClick={() => setOpen(false)} />}
    <aside className={`role-sidebar ${open ? 'open' : ''}`}>
      <div className="role-brand">
        <span><LogoMark inverse /></span>
        <div><strong>DahonMD</strong><small>{role === 'admin' ? 'Admin workspace' : 'Leaf health guide'}</small></div>
        <IconButton label="Close menu" onClick={() => setOpen(false)}><X size={19} /></IconButton>
      </div>
      <p className="role-nav-label">Menu</p>
      <nav>{items.map(([route, label, Icon]) => <button key={route} className={path === route ? 'active' : ''} onClick={() => { navigate(route); setOpen(false); }}><Icon size={18} /><span>{label}</span></button>)}</nav>
      <div className="role-sidebar-spacer" />
      {role === 'farmer' && <div className={`sidebar-network ${online ? '' : 'offline'}`}>{online ? <Cloud size={16} /> : <CloudOff size={16} />}<span>{online ? 'Online' : 'Offline'}</span></div>}
      <div className="sidebar-footer">
        <button className="sidebar-account" onClick={() => navigate(role === 'admin' ? '/admin/profile' : '/farmer/profile')}><span>{user.name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</span><div><strong>{user.name}</strong><small>{role === 'admin' ? 'Administrator' : 'Farmer account'}</small></div></button>
        <button className="sidebar-logout" onClick={signOut}><LogOut size={17} />Log out</button>
      </div>
    </aside>
    <main className="role-main">
      <header className="role-topbar">
        <IconButton label="Open menu" onClick={() => setOpen(true)}><Menu size={21} /></IconButton>
        <div className="role-header-brand"><span><LogoMark /></span><div><strong>DahonMD</strong><small>{currentSection}</small></div></div>
        {role === 'farmer' && <span className={`top-network ${online ? '' : 'offline'}`}>{online ? <Cloud size={15} /> : <CloudOff size={15} />}{online ? 'Online' : 'Offline'}</span>}
      </header>
      <div className="role-page">{children}</div>
    </main>
    {role === 'farmer' && <nav className="farmer-bottom-nav">{FARMER_NAV.map(([route, label, Icon]) => <button key={route} className={path === route ? 'active' : ''} onClick={() => navigate(route)}><Icon size={20} /><span>{label}</span></button>)}</nav>}
  </div>;
}

function RecentCard({ record, onOpen }) {
  const name = record.disease?.name || (record.diseaseId === 'development-unconfigured' ? 'Development result' : titleCase(record.diseaseId)); return <button className="recent-scan-card" onClick={() => onOpen(record)}><span className="recent-thumb">{record.image ? <img src={record.image} alt="Saved banana leaf" /> : <Leaf size={24} />}</span><span className="recent-copy"><strong>{record.confidence < THRESHOLD ? 'Uncertain result' : record.diseaseId === 'healthy' ? 'No supported pattern detected' : name}</strong><small>{confidenceText(record.confidence)} · {record.confidence.toFixed(1)}%</small><small>{formatDate(record.date, true)}</small></span><span className="recent-status">{record.synced ? <><Cloud size={15} />Saved online</> : <><CloudOff size={15} />Waiting to sync</>}</span><ChevronRight size={18} /></button>;
}

function FarmerHome({ user, records, online, navigate, onOpen }) {
  return <div className="role-stack"><section className="farmer-welcome"><p className="eyebrow">HOME</p><h1>Hello, {user.name.split(' ')[0]}.</h1><p>Check your banana plant for possible leaf disease.</p></section><section className="farmer-home-grid"><button className="farmer-scan-hero" onClick={() => navigate('/farmer/scan')}><span className="scan-hero-icon"><Camera size={38} /></span><span><small>START HERE</small><strong>Scan Banana Leaf</strong><p>Take or upload a clear photo to check for a supported visual pattern.</p></span><ChevronRight size={26} /></button><div className="panel quick-help"><span className="section-label">QUICK HELP</span><h2>Helpful before you scan</h2><button onClick={() => navigate('/farmer/scan')}><Camera size={19} /><span><strong>How to take a good leaf photo</strong><small>One leaf, good light, clear focus.</small></span><ChevronRight size={18} /></button><button onClick={() => navigate('/farmer/diseases')}><BookOpen size={19} /><span><strong>Learn about supported diseases</strong><small>Only verified information is shown.</small></span><ChevronRight size={18} /></button><button onClick={() => navigate('/farmer/history')}><History size={19} /><span><strong>What to do after a result</strong><small>Review saved screening results and guidance.</small></span><ChevronRight size={18} /></button></div></section><section className="panel farmer-recent"><div className="panel-heading"><div><span className="section-label">RECENT SCANS</span><h2>Your latest results</h2></div><button className="text-button" onClick={() => navigate('/farmer/history')}>View all<ChevronRight size={17} /></button></div>{records.slice(0, 4).map((record) => <RecentCard key={record.id} record={record} onOpen={onOpen} />)}{!records.length && <Empty title="No scans yet." text="Scan your first banana leaf to start your history." action={() => navigate('/farmer/scan')} actionLabel="Scan Banana Leaf" />}</section><section className={`farmer-sync-banner ${online ? '' : 'offline'}`}>{online ? <Cloud size={22} /> : <CloudOff size={22} />}<div><strong>{online ? 'All saved scans are online' : 'No internet connection'}</strong><p>{online ? 'Your history is connected to your account.' : 'You can check a leaf, but connect before saving the result online.'}</p></div></section></div>;
}

function Tips() { return <div className="scan-tip-card"><strong>For a clearer result:</strong><ul><li><Check size={16} />Photograph one banana leaf at a time.</li><li><Check size={16} />Use good natural or bright lighting.</li><li><Check size={16} />Keep the leaf in focus and the affected area visible.</li><li><Check size={16} />Avoid extreme distance, blur, or covering signs with your hand.</li></ul><small>These steps can improve image quality but do not guarantee diagnostic accuracy.</small></div>; }

function FarmerScan({ onSaved, navigate, online }) {
  const input = useRef(null); const [image, setImage] = useState(null); const [imageFile, setImageFile] = useState(null); const [fileName, setFileName] = useState(''); const [stage, setStage] = useState('choose'); const [result, setResult] = useState(null); const [error, setError] = useState('');
  const useFile = (file) => { if (!file?.type.startsWith('image/')) { setError("We couldn't use this photo. Please choose another image."); return; } if (image?.startsWith('blob:')) URL.revokeObjectURL(image); setImage(URL.createObjectURL(file)); setImageFile(file); setFileName(file.name); setStage('preview'); setError(''); };
  const reset = () => { if (image?.startsWith('blob:')) URL.revokeObjectURL(image); setImage(null); setImageFile(null); setFileName(''); setResult(null); setStage('choose'); setError(''); };
  const check = async () => { setStage('checking'); try { setResult(await analyzeLeaf(image)); setStage('result'); } catch { setError('Something went wrong. Please try again.'); setStage('preview'); } };
  const save = async () => { if (!online) { setError('Connect to the internet before saving this result online.'); return; } try { await onSaved({ diseaseId: result.diseaseId, confidence: result.confidence, latency: result.latency, date: new Date().toISOString(), source: 'web', model: result.model, image: image === '/assets/black-sigatoka-sample.png' ? image : null }, imageFile); navigate('/farmer/history'); } catch { setError('Something went wrong. Please try again.'); } };
  if (stage === 'result') return <FarmerResult image={image} result={result} onReset={reset} onSave={save} error={error} />;
  return <div className="role-stack"><Heading eyebrow="SCAN" title="Scan a Banana Leaf" text="Choose a clear photo, then check it before continuing." /><section className="farmer-scan-layout"><div className="panel scan-photo-panel">{!image ? <div className="friendly-drop" onDrop={(event) => { event.preventDefault(); useFile(event.dataTransfer.files[0]); }} onDragOver={(event) => event.preventDefault()}><span><ImagePlus size={35} /></span><h2>Choose a leaf photo</h2><p>Upload an existing JPG, PNG, or WEBP image.</p><button className="primary-button" onClick={() => input.current?.click()}><Upload size={18} />Choose from Device</button><button className="sample-link" onClick={() => { setImage('/assets/black-sigatoka-sample.png'); setFileName('Development sample'); setStage('preview'); }}>Use development sample</button><input ref={input} hidden type="file" accept="image/*" onChange={(event) => useFile(event.target.files[0])} /></div> : <div className="friendly-preview"><img src={image} alt="Selected banana leaf" />{stage === 'checking' && <div className="checking-cover"><RefreshCw className="spin" size={28} /><strong>Checking the leaf...</strong><p>We are examining visible patterns on the leaf.</p></div>}<span><FileImage size={16} />{fileName}</span></div>}</div><aside className="panel scan-check-panel"><span className="step-number">{image ? '2' : '1'}</span><h2>{image ? 'Check your photo' : 'Take a clear photo'}</h2><p>{image ? 'Is the leaf centered and easy to see?' : 'These short tips can help produce a clearer result.'}</p><Tips /><div className="development-note"><Info size={18} /><p>This development version uses a simulated result. It does not confirm a plant disease.</p></div>{image && <><button className="primary-button full" disabled={stage === 'checking'} onClick={check}><ScanLine size={18} />Use This Photo</button><button className="secondary-button full" disabled={stage === 'checking'} onClick={reset}>Choose Another Photo</button></>}</aside></section>{error && <div className="form-error">{error}</div>}</div>;
}

function FarmerResult({ image, result, onReset, onSave, error }) {
  const uncertain = result.confidence < THRESHOLD; const healthy = result.diseaseId === 'healthy'; const [disease, setDisease] = useState(null);
  useEffect(() => { api('/diseases').then((payload) => setDisease(payload.data.find((item) => item.slug === result.diseaseId) || null)).catch(() => undefined); }, [result.diseaseId]);
  const hasVerifiedGuidance = !uncertain && disease?.is_verified;
  return <div className="role-stack"><section className="result-title"><button className="text-button" onClick={onReset}><ArrowLeft size={18} />Scan another leaf</button><p className="eyebrow">RESULT</p><h1>{uncertain ? "We couldn't identify this leaf confidently." : healthy ? 'No supported disease pattern was strongly detected' : 'Possible Disease'}</h1></section><section className="plain-result-grid"><div className="panel plain-result-image"><img src={image} alt="Scanned banana leaf" /></div><div className={`panel plain-result-summary ${uncertain ? 'uncertain' : healthy ? 'healthy' : ''}`}>{!uncertain && <><span className="section-label">{healthy ? 'SCREENING RESULT' : 'POSSIBLE DISEASE'}</span><h2>{disease?.name || 'Supported class'}</h2></>}<div className="confidence-plain"><strong>{confidenceText(result.confidence)}</strong><span>{result.confidence.toFixed(1)}%</span></div><p>{uncertain ? 'The system could not make a confident match. Try another clear photo. No disease-specific management is shown for an uncertain result.' : 'The image matched visual patterns learned for this supported class. Model confidence is not the probability that the plant truly has the disease.'}</p>{uncertain && <div className="retry-box"><strong>Try again with:</strong><ul><li>Better lighting</li><li>One leaf centered</li><li>The affected area visible</li><li>Less blur</li></ul><button className="primary-button" onClick={onReset}>Take Another Photo</button></div>}</div></section>{hasVerifiedGuidance && <section className="result-guidance"><article className="panel"><span className="section-label">WHAT THIS MEANS</span><p>{healthy ? 'No supported disease pattern was strongly detected in this image. The model covers only its trained classes, so continue monitoring the plant.' : disease.description}</p><span className="section-label">WHAT YOU MAY NOTICE</span>{disease.symptoms?.length ? <ul>{disease.symptoms.map((symptom) => <li key={symptom}><Check size={17} />{symptom}</li>)}</ul> : <p>Insufficient verified evidence available.</p>}</article><article className="panel result-action"><ShieldCheck size={24} /><div><span className="section-label">WHAT YOU CAN DO</span><p>{disease.management || 'Insufficient verified evidence available.'}</p><span className="section-label">WHEN TO ASK FOR HELP</span><p>{disease.professional_referral || 'Ask a qualified agriculture professional if symptoms are severe, unusual, spreading rapidly, or uncertain.'}</p></div></article></section>}<details className="panel attention-panel"><summary><Eye size={18} />Areas the system noticed</summary><div><figure><img src={image} alt="Original leaf" /><figcaption>Original leaf</figcaption></figure><figure className="highlighted"><img src={image} alt="Illustrative highlighted preview" /><i /><figcaption>Development visualization</figcaption></figure></div><p>Highlighted areas contributed more strongly to the simulated result. They do not prove that a pathogen is present.</p></details><Warning />{error && <div className="form-error">{error}</div>}<div className="result-actions-bottom"><button className="secondary-button" onClick={onReset}>Scan Another Leaf</button><button className="primary-button" onClick={onSave}>Save Result</button></div></div>;
}

function Warning() { return <section className="screening-warning"><Info size={20} /><p>This result is a screening aid based on the supported image classes. Some plant diseases and nutrient or environmental problems can look similar. Seek confirmation from a qualified agriculture or plant-health professional when symptoms are severe, unusual, spreading rapidly, or the result is uncertain.</p></section>; }
function Heading({ eyebrow, title, text }) { return <section className="role-page-heading"><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{text}</p></section>; }

function FarmerHistory({ records, navigate, onOpen }) {
  const [query, setQuery] = useState(''); const [kind, setKind] = useState('all'); const [date, setDate] = useState(''); const filtered = records.filter((record) => { const healthy = record.diseaseId === 'healthy'; return (kind === 'all' || (kind === 'healthy' ? healthy : !healthy)) && (!date || record.date?.slice(0, 10) === date) && `${record.disease?.name || record.diseaseId} ${record.id}`.toLowerCase().includes(query.toLowerCase()); });
  return <div className="role-stack"><Heading eyebrow="HISTORY" title="Your Saved Scans" text="Newest results are shown first." /><section className="panel history-role-panel"><div className="friendly-filters"><label><Search size={18} /><input placeholder="Search results" value={query} onChange={(event) => setQuery(event.target.value)} /></label><select aria-label="Filter by result" value={kind} onChange={(event) => setKind(event.target.value)}><option value="all">All results</option><option value="healthy">Healthy</option><option value="disease">Possible disease</option></select><input aria-label="Filter by date" type="date" value={date} onChange={(event) => setDate(event.target.value)} /></div>{filtered.map((record) => <RecentCard key={record.id} record={record} onOpen={onOpen} />)}{!filtered.length && <Empty icon={History} title={records.length ? 'No scans match these filters.' : 'No scans yet.'} text={records.length ? 'Clear a filter and try again.' : 'Scan your first banana leaf to start your history.'} action={!records.length ? () => navigate('/farmer/scan') : undefined} actionLabel="Scan Banana Leaf" />}</section></div>;
}

function DiseaseGuide() {
  const [items, setItems] = useState([]); const [selected, setSelected] = useState(null); const [loading, setLoading] = useState(true); useEffect(() => { api('/diseases').then((payload) => { setItems(payload.data); setSelected(payload.data[0] || null); }).catch(() => setItems([])).finally(() => setLoading(false)); }, []); if (loading) return <Loading text="Loading disease guide..." />;
  return <div className="role-stack"><Heading eyebrow="GUIDE" title="Banana Leaf Disease Guide" text="Only source-verified records appear here." />{!items.length ? <Empty icon={BookOpen} title="DISEASE CONTENT PENDING" text="Final dataset class labels have not yet been established. Disease-specific guidance will remain unavailable until labels and sources are verified." /> : <section className="guide-role-layout"><div className="guide-role-list">{items.map((item) => <button className={selected?.id === item.id ? 'active' : ''} key={item.id} onClick={() => setSelected(item)}>{item.image_url ? <img src={item.image_url} alt="" /> : <span><Leaf size={23} /></span>}<div><strong>{item.name}</strong><small>{item.short_description || item.description}</small></div><ChevronRight size={18} /></button>)}</div>{selected && <article className="panel guide-role-detail">{selected.image_url && <img className="guide-main-image" src={selected.image_url} alt={`Verified representative image for ${selected.name}`} />}<span className="section-label">VERIFIED DISEASE GUIDE</span><h2>{selected.name}</h2>{selected.scientific_name && <p className="scientific-name">{selected.scientific_name}</p>}<section><h3>What it looks like</h3><p>{selected.description}</p><ul>{selected.symptoms?.map((symptom) => <li key={symptom}><Check size={16} />{symptom}</li>)}</ul></section><section><h3>What causes it</h3><p>{selected.causal_agent || 'Insufficient verified evidence available.'}</p></section><section><h3>What you can do</h3><p>{selected.management || 'Insufficient verified evidence available.'}</p></section><section><h3>How to help prevent spread</h3><p>{selected.prevention || 'Insufficient verified evidence available.'}</p></section><section><h3>When to seek expert help</h3><p>{selected.professional_referral || 'Ask a qualified agriculture professional when symptoms are severe, unusual, spreading rapidly, or uncertain.'}</p></section><section><h3>Image-only limitations</h3><p>{selected.image_only_limitations || 'A leaf image cannot provide laboratory confirmation.'}</p></section><Warning /></article>}</section>}</div>;
}

function DiagnosisDialog({ record, onClose }) { if (!record) return null; return <><button className="dialog-scrim" aria-label="Close result" onClick={onClose} /><aside className="diagnosis-dialog"><header><div><span className="section-label">SAVED RESULT</span><h2>{record.confidence < THRESHOLD ? 'Uncertain result' : record.disease?.name || titleCase(record.diseaseId)}</h2></div><IconButton label="Close result" onClick={onClose}><X size={20} /></IconButton></header>{record.image ? <img className="dialog-image" src={record.image} alt="Saved banana leaf" /> : <div className="dialog-image placeholder"><Leaf size={45} /></div>}<div className="confidence-plain"><strong>{confidenceText(record.confidence)}</strong><span>{record.confidence.toFixed(1)}%</span></div><dl><div><dt>Date</dt><dd>{formatDate(record.date, true)}</dd></div><div><dt>Source</dt><dd>{titleCase(record.source)}</dd></div><div><dt>Save status</dt><dd>{record.synced ? 'Saved online' : 'Waiting to sync'}</dd></div></dl><Warning /></aside></>; }

function ProfilePage({ user, onUser, onSignedOut }) {
  const [profile, setProfile] = useState({ name: user.name, email: user.email }); const [passwords, setPasswords] = useState({ current_password: '', password: '', password_confirmation: '' }); const [message, setMessage] = useState(''); const [error, setError] = useState('');
  const save = async (event) => { event.preventDefault(); try { const payload = await api('/profile', { method: 'PUT', body: JSON.stringify(profile) }); onUser(payload.data.user); setMessage('Profile updated.'); } catch (exception) { setError(exception.message); } }; const change = async (event) => { event.preventDefault(); try { await api('/profile/password', { method: 'PUT', body: JSON.stringify(passwords) }); setPasswords({ current_password: '', password: '', password_confirmation: '' }); setMessage('Password updated.'); } catch (exception) { setError(exception.message); } }; const remove = async () => { if (!confirm('Permanently delete your account and diagnosis records?')) return; await api('/profile', { method: 'DELETE' }); setToken(null); onSignedOut(); };
  return <div className="role-stack"><Heading eyebrow="ACCOUNT" title="Profile" text="Keep your account information simple and up to date." /><section className="profile-role-grid"><form className="panel role-form" onSubmit={save}><h2>Edit Profile</h2><label>Name<input value={profile.name} onChange={(event) => setProfile({ ...profile, name: event.target.value })} required /></label><label>Email<input type="email" value={profile.email} onChange={(event) => setProfile({ ...profile, email: event.target.value })} required /></label><button className="primary-button">Save Profile</button></form><form className="panel role-form" onSubmit={change}><h2>Change Password</h2><label>Current password<input type="password" value={passwords.current_password} onChange={(event) => setPasswords({ ...passwords, current_password: event.target.value })} required /></label><label>New password<input type="password" value={passwords.password} onChange={(event) => setPasswords({ ...passwords, password: event.target.value })} required /></label><label>Confirm new password<input type="password" value={passwords.password_confirmation} onChange={(event) => setPasswords({ ...passwords, password_confirmation: event.target.value })} required /></label><button className="secondary-button">Update Password</button><button type="button" className="danger-button" onClick={remove}>Delete Account</button></form></section>{message && <div className="success-message">{message}</div>}{error && <div className="form-error">{error}</div>}</div>;
}

function Stat({ label, value, note, icon: Icon }) { return <article className="admin-stat-card"><span><Icon size={21} /></span><div><small>{label}</small><strong>{value}</strong><p>{note}</p></div></article>; }
function useAdmin(path) { const [data, setData] = useState(null); const [error, setError] = useState(''); useEffect(() => { api(path).then((payload) => setData(payload.data)).catch((exception) => setError(exception.message)); }, [path]); return { data, error }; }
function Distribution({ title, values, extra }) { return <article className="panel admin-distribution"><h2>{title}</h2>{Object.entries(values).map(([label, value]) => <div key={label}><span>{titleCase(label)}</span><strong>{value}</strong></div>)}{!Object.keys(values).length && <p className="empty-copy">No diagnoses yet.</p>}{extra && <div><span>{extra[0]}</span><strong>{extra[1]}</strong></div>}</article>; }
function DiagnosisRows({ items }) { return items.length ? items.map((item) => <div className="admin-record-row" key={item.id}>{item.image_url ? <img src={item.image_url} alt="" /> : <span className="record-placeholder"><Leaf size={20} /></span>}<div><strong>{item.disease?.name || titleCase(item.predicted_class)}</strong><small>{item.user?.name || 'Unknown farmer'}</small></div><span>{item.confidence}%</span><span>{titleCase(item.source)}</span><time>{formatDate(item.diagnosed_at, true)}</time></div>) : <Empty icon={ScanLine} title="No diagnoses yet." text="New saved scans will appear here." />; }

function AdminDashboard() {
  const { data, error } = useAdmin('/admin/dashboard'); if (error) return <div className="form-error">{error}</div>; if (!data) return <Loading text="Loading dashboard..." />;
  return <div className="role-stack"><Heading eyebrow="ADMIN DASHBOARD" title="System Overview" text="Every value below comes from the current database." /><section className="admin-stat-grid"><Stat label="Total Farmers" value={data.total_farmers} note="Farmer accounts" icon={Users} /><Stat label="Total Diagnoses" value={data.total_diagnoses} note="Mobile and web" icon={Database} /><Stat label="Scans Today" value={data.diagnoses_today} note="Current database date" icon={Activity} /><Stat label="Average Model Confidence" value={`${Number(data.average_confidence).toFixed(1)}%`} note="Not biological probability" icon={BarChart3} /><Stat label="Uncertain Results" value={data.uncertain_predictions} note={`${Number(data.uncertain_prediction_rate).toFixed(1)}% of records`} icon={AlertTriangle} /><Stat label="Pending / Failed Syncs" value={data.pending_or_failed_syncs} note="Database sync state" icon={CloudOff} /></section><section className="admin-overview-grid"><Distribution title="Diagnosis Distribution" values={data.diagnoses_per_class} /><Distribution title="Healthy versus Diseased" values={{ healthy: data.healthy_predictions, diseased: data.diseased_predictions }} /><Distribution title="Source Distribution" values={data.diagnoses_per_source} extra={['Simulated records', data.simulated_predictions]} /></section><section className="panel admin-list-panel"><span className="section-label">LATEST ACTIVITY</span><h2>Recent Diagnoses</h2><DiagnosisRows items={data.recent_diagnoses} /></section></div>;
}

function AdminAnalytics() {
  const { data, error } = useAdmin('/admin/analytics'); if (error) return <div className="form-error">{error}</div>; if (!data) return <Loading text="Loading analytics..." />; const timeline = Object.entries(data.diagnoses_over_time); const max = Math.max(1, ...timeline.map(([, total]) => Number(total)));
  return <div className="role-stack"><Heading eyebrow="ANALYTICS" title="Diagnosis Activity" text="Useful research summaries without fabricated performance values." /><section className="admin-stat-grid three"><Stat label="Diagnoses" value={data.total_diagnoses} note="Saved records" icon={Database} /><Stat label="Average Confidence" value={`${Number(data.average_confidence).toFixed(1)}%`} note="Model confidence, not diagnostic certainty" icon={Activity} /><Stat label="Uncertain" value={data.uncertain_predictions} note={`${Number(data.uncertain_prediction_rate).toFixed(1)}% below ${data.confidence_threshold}%`} icon={AlertTriangle} /></section><section className="admin-overview-grid"><article className="panel analytics-chart"><h2>Diagnoses Over Time</h2>{timeline.length ? <div className="timeline-bars">{timeline.map(([date, total]) => <div key={date}><span style={{ height: `${Math.max(8, (Number(total) / max) * 100)}%` }}><b>{total}</b></span><small>{new Date(`${date}T00:00:00`).toLocaleDateString('en-PH', { month: 'short', day: 'numeric' })}</small></div>)}</div> : <p className="empty-copy">No diagnosis activity yet.</p>}</article><Distribution title="Mobile versus Web" values={data.diagnoses_per_source} /><Distribution title="Healthy versus Diseased" values={{ healthy: data.healthy_predictions, diseased: data.diseased_predictions }} /></section></div>;
}

function FarmersAdmin() {
  const empty = { name: '', email: '', password: '', password_confirmation: '' }; const [items, setItems] = useState([]); const [search, setSearch] = useState(''); const [editing, setEditing] = useState(null); const [form, setForm] = useState(empty); const [error, setError] = useState('');
  const load = useCallback(() => api(`/admin/farmers?per_page=50${search ? `&search=${encodeURIComponent(search)}` : ''}`).then((payload) => setItems(payload.data.items)).catch((exception) => setError(exception.message)), [search]); useEffect(() => { load(); }, [load]);
  const edit = (item) => { setEditing(item.id); setForm({ name: item.name, email: item.email, password: '', password_confirmation: '' }); }; const submit = async (event) => { event.preventDefault(); const data = { ...form }; if (editing && !data.password) { delete data.password; delete data.password_confirmation; } try { await api(`/admin/farmers${editing ? `/${editing}` : ''}`, { method: editing ? 'PUT' : 'POST', body: JSON.stringify(data) }); setForm(empty); setEditing(null); setError(''); load(); } catch (exception) { setError(exception.message); } }; const remove = async (item) => { if (!confirm(`Delete farmer ${item.name} and their diagnosis records?`)) return; await api(`/admin/farmers/${item.id}`, { method: 'DELETE' }); load(); };
  return <div className="role-stack"><Heading eyebrow="ADMINISTRATION" title="Farmers" text="Create, search, and maintain farmer accounts." /><form className="admin-search" onSubmit={(event) => { event.preventDefault(); load(); }}><Search size={18} /><input placeholder="Search farmer name or email" value={search} onChange={(event) => setSearch(event.target.value)} /><button className="secondary-button">Search</button></form><form className="panel admin-editor" onSubmit={submit}><h2>{editing ? 'Update Farmer' : 'Create Farmer Account'}</h2><div><label>Name<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /></label><label>Email<input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} required /></label><label>Password<input type="password" value={form.password} onChange={(event) => setForm({ ...form, password: event.target.value })} required={!editing} /></label><label>Confirm password<input type="password" value={form.password_confirmation} onChange={(event) => setForm({ ...form, password_confirmation: event.target.value })} required={!editing} /></label></div><footer><button className="primary-button">{editing ? 'Save Changes' : 'Create Farmer'}</button>{editing && <button type="button" className="secondary-button" onClick={() => { setEditing(null); setForm(empty); }}>Cancel</button>}</footer></form>{error && <div className="form-error">{error}</div>}<section className="panel admin-table-role"><header><span>Farmer</span><span>Joined</span><span>Diagnoses</span><span>Recent Activity</span><span>Actions</span></header>{items.map((item) => <div key={item.id}><span><strong>{item.name}</strong><small>{item.email}</small></span><span>{formatDate(item.created_at)}</span><span>{item.diagnoses_count ?? 0}</span><span>{formatDate(item.last_activity_at, true)}</span><span><button onClick={() => edit(item)}>Edit</button><button className="danger-link" onClick={() => remove(item)}>Delete</button></span></div>)}{!items.length && <Empty icon={Users} title="No farmers found." text="Try another search or create a farmer account." />}</section></div>;
}

function DiagnosesAdmin() {
  const [items, setItems] = useState([]); const [filters, setFilters] = useState({ class: '', source: '', date_from: '', date_to: '', confidence_min: '', confidence_max: '' }); const [error, setError] = useState('');
  const load = useCallback(() => { const query = new URLSearchParams(Object.entries(filters).filter(([, value]) => value)); query.set('per_page', '50'); api(`/admin/diagnoses?${query}`).then((payload) => setItems(payload.data.items)).catch((exception) => setError(exception.message)); }, [filters]); useEffect(() => { load(); }, [load]); const remove = async (item) => { if (!confirm('Delete this diagnosis record?')) return; await api(`/admin/diagnoses/${item.id}`, { method: 'DELETE' }); load(); };
  return <div className="role-stack"><Heading eyebrow="ADMINISTRATION" title="Diagnoses" text="Review original predictions. Predictions cannot be silently edited." /><section className="panel diagnosis-filters"><label>Class<input placeholder="Class slug" value={filters.class} onChange={(event) => setFilters({ ...filters, class: event.target.value })} /></label><label>Source<select value={filters.source} onChange={(event) => setFilters({ ...filters, source: event.target.value })}><option value="">All</option><option value="mobile">Mobile</option><option value="web">Web</option></select></label><label>From<input type="date" value={filters.date_from} onChange={(event) => setFilters({ ...filters, date_from: event.target.value })} /></label><label>To<input type="date" value={filters.date_to} onChange={(event) => setFilters({ ...filters, date_to: event.target.value })} /></label><label>Minimum confidence<input type="number" min="0" max="100" value={filters.confidence_min} onChange={(event) => setFilters({ ...filters, confidence_min: event.target.value })} /></label><label>Maximum confidence<input type="number" min="0" max="100" value={filters.confidence_max} onChange={(event) => setFilters({ ...filters, confidence_max: event.target.value })} /></label></section>{error && <div className="form-error">{error}</div>}<section className="panel admin-table-role diagnoses"><header><span>Image / Result</span><span>Farmer</span><span>Confidence</span><span>Source / Sync</span><span>Date</span><span>Actions</span></header>{items.map((item) => <div key={item.id}><span className="diagnosis-admin-name">{item.image_url ? <img src={item.image_url} alt="" /> : <i><Leaf size={18} /></i>}<strong>{item.disease?.name || titleCase(item.predicted_class)}</strong></span><span>{item.user?.name || 'Unknown farmer'}</span><span>{item.confidence}%</span><span>{titleCase(item.source)} · {item.sync_status || (item.source === 'web' ? 'saved' : 'unknown')}</span><span>{formatDate(item.diagnosed_at, true)}</span><span><button className="danger-link" onClick={() => remove(item)}>Delete</button></span></div>)}{!items.length && <Empty icon={ScanLine} title="No diagnosis records match these filters." text="Change the filters or wait for new scans." />}</section></div>;
}

function DiseasesAdmin() {
  const empty = { slug: '', model_class_key: '', name: '', alternative_names: [], scientific_name: '', causal_agent: '', pathogen_type: '', short_description: '', farmer_summary: '', curative_status: 'unclear_evidence', evidence_level: 'limited', image_only_limitations: '', professional_referral: '', prevention: '' };
  const [items, setItems] = useState([]); const [classes, setClasses] = useState([]); const [contentStatus, setContentStatus] = useState(''); const [form, setForm] = useState(empty); const [editing, setEditing] = useState(null); const [selected, setSelected] = useState(null); const [error, setError] = useState('');
  const load = useCallback(async () => { try { const [knowledge, system] = await Promise.all([api('/admin/diseases'), api('/admin/system')]); setItems(knowledge.data); setClasses(system.data.classes); setContentStatus(system.data.disease_content_status); } catch (exception) { setError(exception.message); } }, []); useEffect(() => { load(); }, [load]);
  const edit = (item) => { setEditing(item.id); setForm({ ...empty, ...item, alternative_names: item.alternative_names || [] }); };
  const submit = async (event) => { event.preventDefault(); try { await api(`/admin/diseases${editing ? `/${editing}` : ''}`, { method: editing ? 'PUT' : 'POST', body: JSON.stringify(form) }); setForm(empty); setEditing(null); setError(''); load(); } catch (exception) { setError(exception.message); } };
  const setStatus = async (item, status) => { try { await api(`/admin/diseases/${item.id}/status`, { method: 'PUT', body: JSON.stringify({ status }) }); setError(''); load(); } catch (exception) { setError(exception.message); } };
  const inspect = async (item) => { try { const payload = await api(`/admin/diseases/${item.id}`); setSelected(payload.data); } catch (exception) { setError(exception.message); } };
  return <div className="role-stack"><Heading eyebrow="ADMIN / RESEARCH" title="Disease Knowledge" text="Draft, research, verify, and audit information tied to the final model labels." /><div className={`development-note ${classes.length === 5 ? '' : 'warning'}`}><Info size={18} /><p>{contentStatus || 'Checking the final label map...'}</p></div>{classes.length === 5 && <form className="panel admin-editor disease-editor" onSubmit={submit}><h2>{editing ? 'Edit content (requires re-review)' : 'Create draft from model label'}</h2><div><label>Model class key<select value={form.model_class_key} onChange={(event) => setForm({ ...form, model_class_key: event.target.value, slug: event.target.value })} required><option value="">Select validated class</option>{classes.map((label) => <option key={label}>{label}</option>)}</select></label><label>Accepted disease name<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /></label><label>Scientific name<input value={form.scientific_name || ''} onChange={(event) => setForm({ ...form, scientific_name: event.target.value })} /></label><label>Causal agent<input value={form.causal_agent || ''} onChange={(event) => setForm({ ...form, causal_agent: event.target.value })} /></label><label>Pathogen type<select value={form.pathogen_type || ''} onChange={(event) => setForm({ ...form, pathogen_type: event.target.value })}><option value="">Not established</option>{['fungus', 'bacterium', 'virus', 'other'].map((value) => <option key={value}>{value}</option>)}</select></label><label>Curative status<select value={form.curative_status} onChange={(event) => setForm({ ...form, curative_status: event.target.value })}>{['unclear_evidence', 'manageable_not_curable', 'no_known_cure', 'curative_treatment_available'].map((value) => <option key={value}>{titleCase(value.replaceAll('_', '-'))}</option>)}</select></label><label>Evidence level<select value={form.evidence_level} onChange={(event) => setForm({ ...form, evidence_level: event.target.value })}>{['limited', 'moderate', 'high'].map((value) => <option key={value}>{titleCase(value)}</option>)}</select></label>{[['short_description','Short description'],['farmer_summary','Farmer summary'],['prevention','How to help prevent spread'],['professional_referral','When to seek expert help'],['image_only_limitations','Image-only limitations']].map(([field,label]) => <label key={field}>{label}<textarea value={form[field] || ''} onChange={(event) => setForm({ ...form, [field]: event.target.value })} /></label>)}</div><footer><button className="primary-button">{editing ? 'Save and return for review' : 'Create Draft'}</button>{editing && <button type="button" className="secondary-button" onClick={() => { setEditing(null); setForm(empty); }}>Cancel</button>}</footer></form>}{error && <div className="form-error">{error}</div>}<section className="panel admin-table-role knowledge-table"><header><span>Disease</span><span>Pathogen</span><span>Status</span><span>Evidence</span><span>Sources</span><span>Last reviewed</span><span>Actions</span></header>{items.map((item) => <div key={item.id}><span><strong>{item.name}</strong><small>{item.model_class_key}</small></span><span>{item.causal_agent || 'Pending'}</span><span><b className={`status-pill ${item.verification_status}`}>{item.verification_status}</b></span><span>{item.evidence_level}</span><span>{item.sources_count ?? 0}</span><span>{formatDate(item.last_reviewed_at)}</span><span><button onClick={() => inspect(item)}>Review</button><button onClick={() => edit(item)}>Edit</button>{item.verification_status === 'researched' && <button onClick={() => setStatus(item, 'verified')}>Verify</button>}<button className="danger-link" onClick={() => setStatus(item, 'archived')}>Archive</button></span></div>)}{!items.length && <Empty icon={BookOpen} title="DISEASE CONTENT PENDING" text="No final model label map is available, so no disease records have been populated." />}</section>{selected && <section className="admin-overview-grid"><article className="panel"><span className="section-label">FARMER CONTENT</span><h2>{selected.disease.name}</h2><p>{selected.disease.description || 'Insufficient verified evidence available.'}</p><h3>Management and Prevention</h3><p>{selected.disease.management || 'Insufficient verified evidence available.'}</p><h3>Image-only limitations</h3><p>{selected.disease.image_only_limitations || 'Not yet documented.'}</p></article><article className="panel"><span className="section-label">RESEARCH EVIDENCE</span><h2>{selected.disease.scientific_name || 'Scientific name pending'}</h2><p><strong>Causal agent:</strong> {selected.disease.causal_agent || 'Pending'}</p><p><strong>Evidence:</strong> {selected.disease.evidence_level}</p><p><strong>Sources:</strong> {selected.disease.sources_count ?? 0}</p>{selected.regulatory_recheck_required && <div className="form-error">REGULATORY RE-CHECK REQUIRED</div>}<button className="secondary-button" onClick={() => setSelected(null)}>Close detail</button></article></section>}</div>;
}

function ResearchSourcesAdmin() {
  const empty = { title: '', authors: '', year: '', journal_or_institution: '', source_type: 'peer_reviewed_article', doi: '', reference_url: '', country_or_region: '', peer_reviewed: true, philippines_specific: false, notes: '' };
  const [items, setItems] = useState([]); const [form, setForm] = useState(empty); const [editing, setEditing] = useState(null); const [filters, setFilters] = useState({ search: '', peer_reviewed: false, philippines_specific: false, institution: '', disease_id: '' }); const [error, setError] = useState('');
  const load = useCallback(() => { const query = new URLSearchParams(Object.entries(filters).filter(([, value]) => value)); api(`/admin/research-sources?${query}`).then((payload) => setItems(payload.data)).catch((exception) => setError(exception.message)); }, [filters]); useEffect(() => { load(); }, [load]);
  const submit = async (event) => { event.preventDefault(); const body = { ...form, year: form.year ? Number(form.year) : null, doi: form.doi || null, reference_url: form.reference_url || null }; try { await api(`/admin/research-sources${editing ? `/${editing}` : ''}`, { method: editing ? 'PUT' : 'POST', body: JSON.stringify(body) }); setEditing(null); setForm(empty); setError(''); load(); } catch (exception) { setError(exception.message); } };
  const edit = (item) => { setEditing(item.id); setForm({ ...empty, ...item, year: item.year || '' }); };
  return <div className="role-stack"><Heading eyebrow="ADMIN / RESEARCH" title="Research Sources" text="Maintain traceable peer-reviewed, authoritative, Philippine, and regulatory evidence." /><section className="panel diagnosis-filters"><label>Search<input value={filters.search} onChange={(event) => setFilters({ ...filters, search: event.target.value })} /></label><label>Institution<input value={filters.institution} onChange={(event) => setFilters({ ...filters, institution: event.target.value })} /></label><label>Disease record ID<input type="number" min="1" value={filters.disease_id} onChange={(event) => setFilters({ ...filters, disease_id: event.target.value })} /></label><label className="check-filter"><input type="checkbox" checked={filters.peer_reviewed} onChange={(event) => setFilters({ ...filters, peer_reviewed: event.target.checked })} /> Peer reviewed</label><label className="check-filter"><input type="checkbox" checked={filters.philippines_specific} onChange={(event) => setFilters({ ...filters, philippines_specific: event.target.checked })} /> Philippines-specific</label></section><form className="panel admin-editor source-editor" onSubmit={submit}><h2>{editing ? 'Update source' : 'Add source'}</h2><div>{[['title','Title'],['authors','Authors'],['year','Publication year'],['journal_or_institution','Journal or institution'],['doi','DOI (leave blank if none)'],['reference_url','Reference URL'],['country_or_region','Country or region']].map(([field,label]) => <label key={field}>{label}<input type={field === 'year' ? 'number' : field === 'reference_url' ? 'url' : 'text'} value={form[field] || ''} onChange={(event) => setForm({ ...form, [field]: event.target.value })} required={['title','authors','journal_or_institution'].includes(field)} /></label>)}<label>Source type<select value={form.source_type} onChange={(event) => setForm({ ...form, source_type: event.target.value })}>{['peer_reviewed_article','systematic_review','review_article','government_guideline','FAO_guideline','university_extension','regulatory_document','academic_book_chapter','research_institute'].map((value) => <option key={value} value={value}>{titleCase(value.replaceAll('_','-'))}</option>)}</select></label><label>Notes<textarea value={form.notes || ''} onChange={(event) => setForm({ ...form, notes: event.target.value })} /></label><label className="check-filter"><input type="checkbox" checked={form.peer_reviewed} onChange={(event) => setForm({ ...form, peer_reviewed: event.target.checked })} /> Peer reviewed</label><label className="check-filter"><input type="checkbox" checked={form.philippines_specific} onChange={(event) => setForm({ ...form, philippines_specific: event.target.checked })} /> Philippines-specific</label></div><footer><button className="primary-button">{editing ? 'Save and trigger re-review' : 'Add Source'}</button>{editing && <button type="button" className="secondary-button" onClick={() => { setEditing(null); setForm(empty); }}>Cancel</button>}</footer></form>{error && <div className="form-error">{error}</div>}<section className="panel admin-table-role source-table"><header><span>Reference</span><span>Year</span><span>Type</span><span>Quality</span><span>Claims</span><span>Actions</span></header>{items.map((item) => <div key={item.id}><span><strong>{item.authors} ({item.year || 'n.d.'}). {item.title}.</strong><small>{item.journal_or_institution}{item.doi ? ` · DOI: ${item.doi}` : ''}</small></span><span>{item.year || 'n.d.'}</span><span>{titleCase(item.source_type.replaceAll('_','-'))}</span><span>{item.peer_reviewed ? 'Peer reviewed' : 'Authoritative'}{item.philippines_specific ? ' · Philippines' : ''}</span><span>{item.evidence_count}</span><span><button onClick={() => edit(item)}>Edit</button>{item.reference_url && <a href={item.reference_url} target="_blank" rel="noreferrer">Open</a>}</span></div>)}{!items.length && <Empty icon={Link2} title="No research sources yet." text="Add only sources that have been checked against the original publication or authority." />}</section></div>;
}

function EvidenceAudit() {
  const { data, error } = useAdmin('/admin/research-sources');
  if (error) return <div className="form-error">{error}</div>;
  if (!data) return <Loading text="Loading claim mappings..." />;
  const claims = data.flatMap((source) => (source.evidence || []).map((evidence) => ({ ...evidence, source })));
  return <section className="panel evidence-audit"><span className="section-label">CLAIM-LEVEL TRACEABILITY</span><h2>Claims using each source</h2>{claims.map((claim) => <article key={claim.id}><strong>{titleCase(claim.claim_type.replaceAll('_', '-'))} · {titleCase(claim.evidence_strength)}</strong><p>{claim.claim_text}</p><small>{claim.disease?.name || 'Disease record'} — {claim.source.authors} ({claim.source.year || 'n.d.'}). {claim.source.title}.{claim.source.doi ? ` DOI: ${claim.source.doi}` : ''}</small></article>)}{!claims.length && <p className="empty-copy">No sources have been mapped to disease claims yet.</p>}</section>;
}

function SystemAdmin() {
  const { data, error } = useAdmin('/admin/system'); if (error) return <div className="form-error">{error}</div>; if (!data) return <Loading text="Loading system information..." />; const fields = [['Model', data.model], ['Attention', data.attention], ['Deployment', data.deployment], ['Version', data.version || 'Not configured'], ['Input size', data.input_size || 'Not configured'], ['Classes', data.classes.length ? data.classes.join(', ') : 'Not configured'], ['Confidence threshold', `${data.confidence_threshold}%`]];
  return <div className="role-stack"><Heading eyebrow="ADMIN / RESEARCH" title="System / Model Information" text="Technical deployment details are visible only to administrators." /><section className="panel system-role-card"><div className="system-mode"><span>AI Mode</span><strong>{data.ai_mode}</strong></div><dl>{fields.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl><div className="development-note"><Info size={18} /><p>Performance values are omitted until validated research artifacts are available.</p></div></section></div>;
}

export default function RoleApp() {
  const first = window.location.pathname; const [path, setPath] = useState(first === '/' ? '/login' : first); const [user, setUser] = useState(null); const [loading, setLoading] = useState(Boolean(getToken())); const [online, setOnline] = useState(navigator.onLine); const [records, setRecords] = useState([]); const [selected, setSelected] = useState(null);
  const navigate = useCallback((next, replace = false) => { window.history[replace ? 'replaceState' : 'pushState']({}, '', next); setPath(next); }, []);
  useEffect(() => { const pop = () => setPath(window.location.pathname); const network = () => setOnline(navigator.onLine); window.addEventListener('popstate', pop); window.addEventListener('online', network); window.addEventListener('offline', network); return () => { window.removeEventListener('popstate', pop); window.removeEventListener('online', network); window.removeEventListener('offline', network); }; }, []);
  useEffect(() => { if (!getToken()) { setLoading(false); return; } api('/auth/me').then((payload) => setUser(payload.data.user)).catch(() => setToken(null)).finally(() => setLoading(false)); }, []);
  const loadRecords = useCallback(() => { if (user?.role !== 'farmer') return; api('/diagnoses?per_page=100').then((payload) => setRecords(payload.data.items.map(mapDiagnosis))).catch(() => setRecords([])); }, [user]); useEffect(loadRecords, [loadRecords]);
  useEffect(() => { if (!loading && !user && !['/login', '/signup'].includes(path)) navigate('/login', true); }, [loading, user, path, navigate]);
  useEffect(() => { if (!user) return; const legacy = ['/', '/dashboard', '/diagnose', '/history', '/profile'].includes(path); const wrong = user.role === 'admin' ? path.startsWith('/farmer') : path.startsWith('/admin'); if (legacy || wrong) navigate(user.role === 'admin' ? '/admin/dashboard' : '/farmer/dashboard', true); }, [user, path, navigate]);
  const signedOut = () => { setUser(null); setRecords([]); navigate('/login', true); }; const save = async (record, imageFile) => { const body = new FormData(); body.append('predicted_class', record.diseaseId); body.append('confidence', String(record.confidence)); body.append('inference_time_ms', String(record.latency)); body.append('model_version', record.model || 'simulated-web-adapter'); body.append('source', 'web'); body.append('diagnosed_at', record.date); if (imageFile) body.append('image', imageFile); const payload = await api('/diagnoses', { method: 'POST', body }); setRecords((current) => [mapDiagnosis(payload.data), ...current]); };
  if (loading) return <Loading text="Restoring your secure session..." />; if (!user) return <AuthPage mode={path === '/signup' ? 'register' : 'login'} onAuthenticated={setUser} navigate={navigate} />;
  if (user.role === 'farmer') { let page = <FarmerHome user={user} records={records} online={online} navigate={navigate} onOpen={setSelected} />; if (path === '/farmer/scan') page = <FarmerScan onSaved={save} navigate={navigate} online={online} />; if (path === '/farmer/history') page = <FarmerHistory records={records} navigate={navigate} onOpen={setSelected} />; if (path === '/farmer/diseases') page = <DiseaseGuide />; if (path === '/farmer/profile') page = <ProfilePage user={user} onUser={setUser} onSignedOut={signedOut} />; return <Shell role="farmer" user={user} path={path} navigate={navigate} onSignedOut={signedOut} online={online}>{page}<DiagnosisDialog record={selected} onClose={() => setSelected(null)} /></Shell>; }
  let page = <AdminDashboard />; if (path === '/admin/farmers') page = <FarmersAdmin />; if (path === '/admin/diagnoses') page = <DiagnosesAdmin />; if (path === '/admin/diseases') page = <DiseasesAdmin />; if (path === '/admin/sources') page = <><ResearchSourcesAdmin /><EvidenceAudit /></>; if (path === '/admin/analytics') page = <AdminAnalytics />; if (path === '/admin/system') page = <SystemAdmin />; if (path === '/admin/profile') page = <ProfilePage user={user} onUser={setUser} onSignedOut={signedOut} />; return <Shell role="admin" user={user} path={path} navigate={navigate} onSignedOut={signedOut} online={online}>{page}</Shell>;
}
